62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
74	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
102	        Collection<Owner> owners;
103	        if (lastName != null) {
104	            owners = this.clinicService.findOwnerByLastName(lastName);
105	        } else {
106	            owners = this.clinicService.findAllOwners();
107	        }
108	        if (owners.isEmpty()) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        List<OwnerDto> ownerDtos = owners.stream()
112	            .map(this::toOwnerDtoWithBulkWarning)
113	            .toList();
114	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
132	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
133	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        requireNonBlank(missingFields, "address", normalizedAddress);
135	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
136	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingRequiredFieldsException(missingFields);
139	        }
140	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
141	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
142	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
143	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
144	        requireDailyLimitNotReached(registrationDate);
145	        requireCityBelowCapacity(ownerFieldsDto.getCity());
146	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
147	        ownerFieldsDto.setTelephone(normalizedTelephone);
148	        if (ownerFieldsDto.getEmail() != null) {
149	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
150	        }
151	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        owner.setAddress(normalizedAddress);
155	        owner.setRegistrationDate(registrationDate);
156	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
157	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
158	        if (sharesHousehold) {
159	            owner.setHouseholdId(householdIdFor(normalizeForHousehold(owner.getLastName()),
160	                householdAddressKey(owner.getAddress())));
161	        }
162	        requireUniqueIdentity(owner);
163	        if (sharesHousehold) {
164	            backfillHousehold(owner.getLastName(), owner.getAddress(), owner.getHouseholdId());
165	        }
166	        this.clinicService.saveOwner(owner);
167	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
168	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
169	            ownerMapper.toMembershipLevel(owner));
170	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        currentOwner.setAddress(ownerFieldsDto.getAddress());
184	        currentOwner.setCity(ownerFieldsDto.getCity());
185	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
186	        currentOwner.setLastName(ownerFieldsDto.getLastName());
187	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
188	        this.clinicService.saveOwner(currentOwner);
189	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Transactional
194	    @Override
195	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        this.clinicService.deleteOwner(owner);
201	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        HttpHeaders headers = new HttpHeaders();
212	        Pet pet = petMapper.toPet(petFieldsDto);
213	        owner.setId(ownerId);
214	        pet.setOwner(owner);
215	        pet.getType().setName(null);
216	        this.clinicService.savePet(pet);
217	        PetDto petDto = petMapper.toPetDto(pet);
218	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
219	            .buildAndExpand(pet.getId()).toUri());
220	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
221	    }
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
226	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
227	        if (currentOwner != null) {
228	            Pet currentPet = this.clinicService.findPetById(petId);
229	            if (currentPet != null) {
230	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
231	                currentPet.setName(petFieldsDto.getName());
232	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
233	                this.clinicService.savePet(currentPet);
234	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
235	            }
236	        }
237	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
243	        HttpHeaders headers = new HttpHeaders();
244	        Visit visit = visitMapper.toVisit(visitFieldsDto);
245	        Pet pet = new Pet();
246	        pet.setId(petId);
247	        visit.setPet(pet);
248	        this.clinicService.saveVisit(visit);
249	        VisitDto visitDto = visitMapper.toVisitDto(visit);
250	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
251	            .buildAndExpand(visit.getId()).toUri());
252	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
253	    }
254	
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner != null) {
261	            Pet pet = owner.getPet(petId);
262	            if (pet != null) {
263	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
264	            }
265	        }
266	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
267	    }
268	
269	    /**
270	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
271	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
272	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
273	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
274	     *
275	     * @param city the owner's city (already validated non-blank)
276	     * @param lastName the owner's last name (already validated non-blank)
277	     * @return the formatted customer code for the owner being created
278	     */
279	    private String nextCustomerCode(String city, String lastName) {
280	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
281	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
282	        int sequence = (int) this.clinicService.findAllOwners().stream()
283	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
284	            .count() + 1;
285	        return String.format("%s-%s-%04d", city3, last3, sequence);
286	    }
287	
288	    /**
289	     * Counts the existing owners (those already persisted before this create) whose first and last
290	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
291	     * the new owner as its {@code namesakeCount} and echoed back on reads.
292	     *
293	     * @param firstName the incoming owner's first name (already validated non-blank)
294	     * @param lastName the incoming owner's last name (already validated non-blank)
295	     * @return the number of existing namesakes sharing both names case-insensitively
296	     */
297	    private int countNamesakes(String firstName, String lastName) {
298	        return (int) this.clinicService.findAllOwners().stream()
299	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
300	                && lastName.equalsIgnoreCase(existing.getLastName()))
301	            .count();
302	    }
303	
304	    /**
305	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
306	     * whitespace-only), so the caller can reject the request listing every offending field.
307	     */
308	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
309	        if (value == null || value.isBlank()) {
310	            missingFields.add(fieldName);
311	        }
312	    }
313	
314	    /**
315	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
316	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
317	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
318	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
319	     * {@code "+61412345678"}.
320	     *
321	     * @param telephone the raw telephone value from the request
322	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
323	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
324	     */
325	    private static String normalizeTelephone(String telephone) {
326	        String e164 = toE164(telephone);
327	        if (e164 == null) {
328	            throw new InvalidFieldValueException("telephone",
329	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
330	        }
331	        return e164;
332	    }
333	
334	    /**
335	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
336	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
337	     * owners' stored numbers when detecting duplicates.
338	     */
339	    private static String toE164(String telephone) {
340	        if (telephone == null) {
341	            return null;
342	        }
343	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
344	        String digits;
345	        if (cleaned.startsWith("+")) {
346	            digits = cleaned.substring(1);
347	        } else {
348	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
349	            digits = "61" + national;
350	        }
351	        if (!digits.matches("[0-9]{8,15}")) {
352	            return null;
353	        }
354	        if (!hasValidNationalLength(digits)) {
355	            return null;
356	        }
357	        return "+" + digits;
358	    }
359	
360	    /**
361	     * Checks the national-number length against the country code for the country codes that pin one.
362	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
363	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
364	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
365	     */
366	    private static boolean hasValidNationalLength(String digits) {
367	        if (digits.startsWith("61")) {
368	            return digits.length() - 2 == 9;
369	        }
370	        if (digits.startsWith("1")) {
371	            return digits.length() - 1 == 10;
372	        }
373	        return true;
374	    }
375	
376	    /**
377	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
378	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
379	     *
380	     * @param email the raw email value from the request (already known to be non-null)
381	     * @return the lower-cased email to be stored and returned
382	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
383	     */
384	    private static String normalizeEmail(String email) {
385	        String trimmed = email.trim();
386	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
387	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
388	        }
389	        return trimmed.toLowerCase(Locale.ROOT);
390	    }
391	
392	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
393	    private static final int MAX_OWNERS_PER_CITY = 50;
394	
395	    /**
396	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
397	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
398	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
399	     *
400	     * @param city the incoming owner's city (already validated non-blank)
401	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
402	     */
403	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
404	    private static final int MAX_OWNERS_PER_DAY = 100;
405	
406	    /**
407	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
408	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
409	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
410	     * date rolled forward to a business day), so this caps the number that may be created per day.
411	     *
412	     * @param businessDay the adjusted business-day registration date of the owner being created
413	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
414	     */
415	    /**
416	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
417	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
418	     */
419	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
420	
421	    /**
422	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
423	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
424	     * owner's registration date, otherwise {@code false}.
425	     *
426	     * @param owner the owner to map
427	     * @return the owner DTO with its bulk-signup warning flag populated
428	     */
429	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
430	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
431	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
432	        return ownerDto;
433	    }
434	
435	    /**
436	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
437	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
438	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
439	     */
440	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
441	        if (registrationDate == null) {
442	            return false;
443	        }
444	        long registeredThatDay = this.clinicService.findAllOwners().stream()
445	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
446	            .count();
447	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
448	    }
449	
450	    private void requireDailyLimitNotReached(LocalDate businessDay) {
451	        long registeredThatDay = this.clinicService.findAllOwners().stream()
452	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
453	            .count();
454	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
455	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
456	        }
457	    }
458	
459	    /**
460	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
461	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
462	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
463	     * is recorded on the next business day, and every value derived from the registration date uses the
464	     * adjusted date.
465	     *
466	     * @param date the effective registration date (supplied or defaulted), never {@code null}
467	     * @return the same date, or the next Monday when {@code date} is a weekend
468	     */
469	    private static LocalDate toBusinessDay(LocalDate date) {
470	        DayOfWeek day = date.getDayOfWeek();
471	        if (day == DayOfWeek.SATURDAY) {
472	            return date.plusDays(2);
473	        }
474	        if (day == DayOfWeek.SUNDAY) {
475	            return date.plusDays(1);
476	        }
477	        return date;
478	    }
479	
480	    /** Matches a well-formed postcode: exactly four decimal digits. */
481	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
482	
483	    /**
484	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
485	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
486	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
487	     * present here and accepts any well-formed postcode.
488	     */
489	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
490	        "NSW", new int[] {2000, 2099},
491	        "VIC", new int[] {3000, 3099},
492	        "QLD", new int[] {4000, 4099});
493	
494	    /**
495	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
496	     * optional, so the request contract stays backward-compatible). When present it must be exactly
497	     * four digits and, for a city whose region is known, fall within that region's inclusive range
498	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
499	     * postcode. A malformed or out-of-range value is rejected with a 400.
500	     *
501	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
502	     * @param city the owner's city, used to look up the region whose range constrains the postcode
503	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
504	     */
505	    private void validatePostcode(String postcode, String city) {
506	        if (postcode == null) {
507	            return;
508	        }
509	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
510	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
511	        }
512	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
513	        int[] range = REGION_POSTCODES.get(region);
514	        if (range == null) {
515	            return;
516	        }
517	        int value = Integer.parseInt(postcode);
518	        if (value < range[0] || value > range[1]) {
519	            throw new InvalidFieldValueException("postcode",
520	                "Postcode must be valid for the city's region " + region);
521	        }
522	    }
523	
524	    private void requireCityBelowCapacity(String city) {
525	        long cityOwners = this.clinicService.findAllOwners().stream()
526	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
527	            .count();
528	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
529	            throw new CityAtCapacityException(city);
530	        }
531	    }
532	
533	    /**
534	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
535	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
536	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
537	     * former separate telephone, email and household checks. Because the telephone is part of the
538	     * key, two members of the same household (same {@code householdId}) with different telephones
539	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
540	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
541	     *
542	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
543	     *              already populated
544	     * @throws DuplicateIdentityException if another owner already has this exact identity key
545	     */
546	    private void requireUniqueIdentity(Owner owner) {
547	        String identityKey = ownerMapper.toIdentityKey(owner);
548	        boolean taken = this.clinicService.findAllOwners().stream()
549	            .map(ownerMapper::toIdentityKey)
550	            .anyMatch(identityKey::equals);
551	        if (taken) {
552	            throw new DuplicateIdentityException(identityKey);
553	        }
554	    }
555	
556	    /**
557	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
558	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
559	     * comparisons are case-insensitive.
560	     */
561	    private static String normalizeForHousehold(String value) {
562	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
563	    }
564	
565	    /**
566	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
567	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
568	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
569	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
570	     * value normalizes to the empty string, so the required-field check rejects an address that is
571	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
572	     *
573	     * @param address the raw address value from the request (may be {@code null})
574	     * @return the normalized address, or the empty string when blank after normalization
575	     */
576	    private static String normalizeAddress(String address) {
577	        if (address == null) {
578	            return "";
579	        }
580	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
581	        if (collapsed.isEmpty()) {
582	            return "";
583	        }
584	        String[] tokens = collapsed.split(" ");
585	        StringBuilder sb = new StringBuilder();
586	        for (String token : tokens) {
587	            String expanded = switch (token) {
588	                case "ST" -> "STREET";
589	                case "RD" -> "ROAD";
590	                case "AVE" -> "AVENUE";
591	                default -> token;
592	            };
593	            if (sb.length() > 0) {
594	                sb.append(' ');
595	            }
596	            sb.append(expanded);
597	        }
598	        return sb.toString();
599	    }
600	
601	    /**
602	     * Derives the comparison key for an address used by household-duplicate detection and the shared
603	     * household identifier: the address is first put in its canonical normalized form and then
604	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
605	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
606	     */
607	    private static String householdAddressKey(String address) {
608	        return normalizeForHousehold(normalizeAddress(address));
609	    }
610	
611	    /**
612	     * Back-fills the shared {@code householdId} onto every existing member of the household
613	     * identified by this last name and address (same normalized last name and address) that does not
614	     * already carry it, so the whole household agrees on the identifier. Members that predate this
615	     * feature (or were created without opting in) are updated to the shared value. Called only after
616	     * the joining owner has passed the identity check, so a rejected request leaves existing owners
617	     * untouched.
618	     *
619	     * @param lastName the joining owner's last name (already validated non-blank)
620	     * @param address the joining owner's address (already validated non-blank)
621	     * @param householdId the shared household identifier for this last name and address
622	     */
623	    private void backfillHousehold(String lastName, String address, String householdId) {
624	        String normalizedLastName = normalizeForHousehold(lastName);
625	        String normalizedAddress = householdAddressKey(address);
626	        this.clinicService.findAllOwners().stream()
627	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
628	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
629	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
630	            .forEach(existing -> {
631	                existing.setHouseholdId(householdId);
632	                this.clinicService.saveOwner(existing);
633	            });
634	    }
635	
636	    /**
637	     * Derives a stable household identifier from the already-normalized last name and address as the
638	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
639	     * always maps to the same identifier.
640	     */
641	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
642	        try {
643	            byte[] digest = MessageDigest.getInstance("SHA-256")
644	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
645	            StringBuilder sb = new StringBuilder();
646	            for (byte b : digest) {
647	                sb.append(String.format("%02X", b));
648	            }
649	            return sb.substring(0, 12);
650	        }
651	        catch (NoSuchAlgorithmException e) {
652	            throw new IllegalStateException("SHA-256 not available", e);
653	        }
654	    }
655	}
